17	// maxCopilotLineBytes bounds the scanner buffer when reading events.jsonl;
18	// individual Copilot events (e.g. large tool payloads) can exceed bufio's
19	// default 64 KB line limit.
20	const maxCopilotLineBytes = 10 * 1024 * 1024
21	
22	// copilotImporter imports Copilot CLI transcripts. Copilot stores sessions
23	// flat (~/.copilot/session-state/<id>/events.jsonl), not per-repo, so Discover
24	// reads each session's session.start event and keeps only those whose
25	// cwd/gitRoot is the repo root or a descendant.
26	type copilotImporter struct{}
27	
28	func (copilotImporter) Name() string { return string(agent.AgentNameCopilotCLI) }
29	
30	func (copilotImporter) AgentType() types.AgentType { return agent.AgentTypeCopilotCLI }
31	
32	// Discover returns Copilot session transcripts belonging to this repo (by the
33	// session.start context) modified within the lookback window. The session ID is
34	// the session-state subdirectory name.
35	func (copilotImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
36		dir, err := resolveDir(repoRoot, overridePath, "copilot", (&copilotcli.CopilotCLIAgent{}).GetSessionDir)
37		if err != nil {
38			return nil, err
39		}
40		// Each session is a subdirectory holding events.jsonl; keep only those whose
41		// session.start places them in this repo.
42		return discoverSessionFiles(dir, now, sessionFilter, func(dir string, e os.DirEntry) (string, string, bool) {
43			if !e.IsDir() {
44				return "", "", false
45			}
46			path := filepath.Join(dir, e.Name(), "events.jsonl")
47			if !copilotSessionInRepo(path, repoRoot) {
48				return "", "", false
49			}
50			return e.Name(), path, true
51		})
52	}
53	
54	// copilotSessionInRepo reports whether the session's session.start event places
55	// it in this repo (gitRoot or cwd is the repo root or a descendant). Sessions
56	// whose location can't be determined are treated as not belonging to the repo.
57	func copilotSessionInRepo(path, repoRoot string) bool {
58		f, err := os.Open(path) //nolint:gosec // path discovered under the configured session dir
59		if err != nil {
60			return false
61		}
62		defer func() { _ = f.Close() }()
63	
64		// Scan line-by-line and stop at the first session.start (normally line 0)
65		// rather than slurping the whole transcript, which can be large.
66		scanner := bufio.NewScanner(f)
67		scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), maxCopilotLineBytes)
68		for scanner.Scan() {
69			var evt struct {
70				Type string `json:"type"`
71				Data struct {
72					Context struct {
73						Cwd     string `json:"cwd"`
74						GitRoot string `json:"gitRoot"`
75					} `json:"context"`
76				} `json:"data"`
77			}
78			if err := json.Unmarshal(scanner.Bytes(), &evt); err != nil || evt.Type != "session.start" {
79				continue
80			}
81			return repoMatches(evt.Data.Context.GitRoot, repoRoot) || repoMatches(evt.Data.Context.Cwd, repoRoot)
82		}
83		return false
84	}
85	
86	// SplitTurns produces one Turn per user.message event, bounded by the next.
87	// Token usage is delegated to the Copilot agent (per-turn slices sum
88	// assistant.message outputTokens); the model is read once from the transcript.
89	func (copilotImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
90		ag := &copilotcli.CopilotCLIAgent{}
91		model := copilotcli.ExtractModelFromTranscript(context.Background(), sf.Path)
92		return splitLineTurns(splitRawLines(full),
93			func(raw []byte) bool { _, ok := copilotPromptText(raw); return ok },
94			func(rawLines [][]byte, start, _ int, truncated []byte) (*Turn, error) {
95				tokens, err := ag.CalculateTokenUsage(truncated, start)
96				if err != nil {
97					return nil, fmt.Errorf("token usage: %w", err)
98				}
99				var evt struct {
100					ID        string `json:"id"`
101					Timestamp string `json:"timestamp"`
102				}
103				if err := json.Unmarshal(rawLines[start], &evt); err != nil {
104					//nolint:nilerr // skip defensively; the line already parsed in copilotPromptText
105					return nil, nil
106				}
107				prompt, _ := copilotPromptText(rawLines[start])
108				return &Turn{UUID: evt.ID, Prompt: prompt, Model: model, CreatedAt: parseTimestamp(evt.Timestamp), Tokens: tokens}, nil
109			})
110	}
111	
112	// copilotPromptText reports whether a raw events.jsonl line is a user.message
113	// and returns its content. Other event types return false.
114	func copilotPromptText(raw []byte) (string, bool) {
115		var evt struct {
116			Type string `json:"type"`
117			Data struct {
118				Content string `json:"content"`
119			} `json:"data"`
120		}
121		if err := json.Unmarshal(raw, &evt); err != nil || evt.Type != "user.message" {
122			return "", false
123		}
124		if evt.Data.Content == "" {
125			return "", false
126		}
127		return evt.Data.Content, true
