21	// codexImporter imports Codex rollout transcripts. Codex stores sessions
22	// globally (CODEX_HOME/sessions/YYYY/MM/DD/rollout-*.jsonl), not per-repo, so
23	// Discover walks the tree and keeps only sessions whose session_meta cwd is the
24	// repo root or a descendant of it.
25	type codexImporter struct{}
26	
27	func (codexImporter) Name() string { return string(agent.AgentNameCodex) }
28	
29	func (codexImporter) AgentType() types.AgentType { return agent.AgentTypeCodex }
30	
31	// codexSessionMeta is the subset of a Codex session_meta payload import needs.
32	type codexSessionMeta struct {
33		ID  string `json:"id"`
34		Cwd string `json:"cwd"`
35	}
36	
37	// Discover walks the Codex sessions tree and returns transcripts belonging to
38	// this repo (by session_meta cwd) modified within the lookback window.
39	func (codexImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
40		dir, err := resolveDir(repoRoot, overridePath, "codex", (&codex.CodexAgent{}).GetSessionDir)
41		if err != nil {
42			return nil, err
43		}
44		cutoff := now.AddDate(0, 0, -LookbackDays)
45		var out []SessionFile
46		walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
47			if err != nil {
48				if os.IsNotExist(err) {
49					return nil // missing root or vanished entry: nothing to import
50				}
51				return err
52			}
53			if d.IsDir() || !strings.HasSuffix(d.Name(), ".jsonl") {
54				return nil
55			}
56			info, statErr := d.Info()
57			if statErr != nil || info.ModTime().Before(cutoff) {
58				return nil //nolint:nilerr // skip unreadable/old entries, keep walking
59			}
60			meta, metaErr := codexReadSessionMeta(path)
61			if metaErr != nil || !repoMatches(meta.Cwd, repoRoot) {
62				return nil //nolint:nilerr // skip sessions we can't attribute to this repo
63			}
64			sessionID := meta.ID
65			if sessionID == "" {
66				sessionID = strings.TrimSuffix(d.Name(), ".jsonl")
67			}
68			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, sessionID) {
69				return nil
70			}
71			out = append(out, SessionFile{Path: path, SessionID: sessionID})
72			return nil
73		})
74		if walkErr != nil {
75			return nil, fmt.Errorf("walk codex sessions: %w", walkErr)
76		}
77		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
78		return out, nil
79	}
80	
81	// codexReadSessionMeta reads the first JSONL line of a rollout file and returns
82	// its session_meta payload. The first line must be session_meta by Codex's
83	// format.
84	func codexReadSessionMeta(path string) (codexSessionMeta, error) {
85		f, err := os.Open(path) //nolint:gosec // path discovered by walking the configured session dir
86		if err != nil {
87			return codexSessionMeta{}, fmt.Errorf("open rollout: %w", err)
88		}
89		defer func() { _ = f.Close() }()
90		r := bufio.NewReader(f)
91		first, err := r.ReadBytes('\n')
92		if len(first) == 0 && err != nil {
93			return codexSessionMeta{}, fmt.Errorf("read session_meta line: %w", err)
94		}
95		var line struct {
96			Type    string           `json:"type"`
97			Payload codexSessionMeta `json:"payload"`
98		}
99		if jsonErr := json.Unmarshal(first, &line); jsonErr != nil || line.Type != "session_meta" {
100			return codexSessionMeta{}, errors.New("first line is not session_meta")
101		}
102		return line.Payload, nil
103	}
104	
105	// SplitTurns produces one Turn per user response_item, bounded by the next.
106	// Codex response_items carry no per-message UUID, so the turn's stable key is
107	// its (append-only) start line index. Token usage is delegated to the Codex
108	// agent, which computes the cumulative-usage delta for the line range.
109	func (codexImporter) SplitTurns(_ SessionFile, full []byte) ([]Turn, error) {
110		ag := &codex.CodexAgent{}
111		return splitLineTurns(splitRawLines(full),
112			func(raw []byte) bool { _, ok := codexPromptText(raw); return ok },
113			func(rawLines [][]byte, start, _ int, truncated []byte) (*Turn, error) {
114				tokens, err := ag.CalculateTokenUsage(truncated, start)
115				if err != nil {
116					return nil, fmt.Errorf("token usage: %w", err)
117				}
118				prompt, _ := codexPromptText(rawLines[start])
119				return &Turn{
120					UUID:      strconv.Itoa(start),
121					Prompt:    prompt,
122					CreatedAt: codexLineTime(rawLines[start]),
123					Tokens:    tokens,
124				}, nil
125			})
126	}
127	
128	// codexPromptText reports whether a raw rollout line is a user-prompt
129	// response_item and returns its concatenated input_text. Assistant messages,
130	// tool calls, and event_msg lines return false.
131	func codexPromptText(raw []byte) (string, bool) {
132		var line struct {
133			Type    string          `json:"type"`
134			Payload json.RawMessage `json:"payload"`
135		}
136		if err := json.Unmarshal(raw, &line); err != nil || line.Type != "response_item" {
137			return "", false
138		}
139		var payload struct {
140			Type    string `json:"type"`
141			Role    string `json:"role"`
142			Content []struct {
143				Type string `json:"type"`
144				Text string `json:"text"`
145			} `json:"content"`
146		}
147		if err := json.Unmarshal(line.Payload, &payload); err != nil {
148			return "", false
149		}
150		if payload.Type != "message" || payload.Role != "user" {
151			return "", false
152		}
153		var texts []string
154		for _, item := range payload.Content {
155			if item.Type == "input_text" {
156				if t := strings.TrimSpace(item.Text); t != "" {
157					texts = append(texts, t)
158				}
159			}
160		}
161		if len(texts) == 0 {
162			return "", false
163		}
164		return strings.Join(texts, "\n\n"), true
165	}
166	
167	// codexLineTime returns the RFC3339 timestamp on a rollout line, or the zero
168	// time when absent or unparseable.
169	func codexLineTime(raw []byte) time.Time {
170		var line struct {
171			Timestamp string `json:"timestamp"`
172		}
173		if err := json.Unmarshal(raw, &line); err != nil {
174			return time.Time{}
175		}
176		return parseTimestamp(line.Timestamp)
177	}
178	
179	// repoMatches reports whether cwd is the repo root or a descendant of it. Both
180	// paths are normalized (cleaned, symlinks resolved best-effort) before
181	// comparison. Used by the global/flat-store importers (Codex, Copilot) to keep
182	// only sessions belonging to this repo.
183	func repoMatches(cwd, repoRoot string) bool {
184		if cwd == "" || repoRoot == "" {
185			return false
186		}
187		rel, err := filepath.Rel(normalizePath(repoRoot), normalizePath(cwd))
188		if err != nil {
189			return false
190		}
191		return !strings.HasPrefix(rel, "..")
192	}
193	
194	// normalizePath cleans a path and resolves symlinks when possible, so a cwd
195	// recorded through a symlinked path (e.g. macOS /var → /private/var) still
196	// matches the repo root. Falls back to the cleaned path when the target does
197	// not exist on this machine.
198	func normalizePath(p string) string {
199		cleaned := filepath.Clean(p)
200		if resolved, err := filepath.EvalSymlinks(cleaned); err == nil {
201			return resolved
202		}
203		return cleaned
204	}
