18	// envelope ({"type":"message","id":..,"message":{...}}); token usage is
19	// subagent-aware and the model lives in an adjacent <id>.settings.json.
20	type factoryImporter struct{}
21	
22	func (factoryImporter) Name() string { return string(agent.AgentNameFactoryAIDroid) }
