36	// SplitTurns produces one Turn per user-prompt envelope, bounded by the next.
37	// Token usage (including spawned subagents) is delegated to the Factory agent;
38	// the model is read once from the session's adjacent settings file. Droid
39	// envelopes carry no per-message timestamp (the agent stamps events with
40	// time.Now() at hook time), so every turn falls back to the transcript file's
41	// modtime — the same fallback the Gemini importer uses.
42	func (factoryImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
43		subagentsDir := filepath.Join(filepath.Dir(sf.Path), sf.SessionID, "subagents")
44		model := factoryaidroid.ExtractModelFromTranscript(sf.Path)
45		var createdAt time.Time
46		if info, statErr := os.Stat(sf.Path); statErr == nil {
47			createdAt = info.ModTime()
48		}
49		ag := &factoryaidroid.FactoryAIDroidAgent{}
50		return splitLineTurns(splitRawLines(full),
51			func(raw []byte) bool { _, ok := factoryPromptText(raw); return ok },
52			func(rawLines [][]byte, start, _ int, truncated []byte) (*Turn, error) {
53				tokens, err := ag.CalculateTotalTokenUsage(truncated, start, subagentsDir)
54				if err != nil {
55					return nil, fmt.Errorf("token usage: %w", err)
56				}
57				var env struct {
